mapper.select:







SELECT n.operation_id, d.defect_type_id, MIN(d.defect_type_name_snapshot) type_name, COUNT(DISTINCT d.defect_type_name_snapshot) type_name_variants,
  d.waste_category waste_category,
  SUM(d.defect_qty) declared_qty,
  SUM(CASE WHEN t.attribution=#{independent} THEN d.defect_qty ELSE 0 END) independent_qty,
  SUM(CASE WHEN t.attribution=#{overlap} THEN d.defect_qty ELSE 0 END) overlap_qty,
  SUM(CASE WHEN COALESCE(t.attribution,#{unverified})=#{unverified} THEN d.defect_qty ELSE 0 END) unverified_qty,
  SUM(CASE WHEN t.attribution=#{independent} THEN t.returned ELSE 0 END) returned_qty,
  SUM(CASE WHEN t.attribution=#{independent} THEN d.defect_qty-t.returned ELSE 0 END) net_defect_qty,
  SUM(COALESCE(t.invalid_actions,0)) invalid_actions
FROM mes_production_defect d
JOIN routing_node n ON n.id=d.affected_node_id
LEFT JOIN (
  SELECT declaration_id,declaration_revision, MAX(CASE WHEN action_type=#{assessAction} THEN attribution_type END) attribution, SUM(CASE WHEN action_type=#{return_nodeAction} THEN rework_qty ELSE 0 END) returned
   , SUM(CASE WHEN action_type NOT IN (#{assessAction},#{return_nodeAction},#{transfer_warehouseAction}) THEN 1 ELSE 0 END) invalid_actions
  FROM mes_quality_treatment GROUP BY declaration_id,declaration_revision
) t ON t.declaration_id=d.declaration_id AND t.declaration_revision=d.revision_no
WHERE d.record_action != #{voidAction}
  AND NOT EXISTS (SELECT 1 FROM mes_production_defect newer WHERE newer.declaration_id=d.declaration_id AND newer.revision_no>d.revision_no)
AND d.execution_id=#{executionId}
AND n.operation_id=#{operationId}
AND d.defect_type_id=#{defectTypeId}
AND d.waste_category=#{wasteCategory}
AND COALESCE(t.attribution,#{unverified})=#{attribution}
AND d.occurred_at>=#{from}
AND d.occurred_at<=#{to}
GROUP BY n.operation_id,d.defect_type_id,d.waste_category
ORDER BY n.operation_id,d.defect_type_id,d.waste_category
